import * as THREE from 'three';
import {OrbitControls} from 'coco/orbit';
import {GLTFLoader} from 'coco/gltf';

const $=s=>document.querySelector(s);
const stage=$('#stage'),bubbleLayer=$('#bubbles');
const mobile=matchMedia('(max-width: 800px)').matches||navigator.deviceMemory&&navigator.deviceMemory<=4;
const scene=new THREE.Scene();scene.background=new THREE.Color('#dce6e5');scene.fog=new THREE.Fog('#dce6e5',75,210);
const renderer=new THREE.WebGLRenderer({antialias:!mobile,powerPreference:mobile?'low-power':'high-performance'});
renderer.setPixelRatio(mobile?1:Math.min(devicePixelRatio,1.25));renderer.setSize(innerWidth,innerHeight);
renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
renderer.shadowMap.enabled=!mobile;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.localClippingEnabled=true;stage.append(renderer.domElement);
const perspective=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.05,500);
const ortho=new THREE.OrthographicCamera(-18,18,12,-12,.05,500);let camera=perspective;
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.49;controls.minDistance=1.5;controls.maxDistance=180;
const sun=new THREE.DirectionalLight('#fff0d8',2.0);sun.position.set(30,42,26);sun.castShadow=!mobile;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=sun.shadow.camera.bottom=-38;sun.shadow.camera.right=sun.shadow.camera.top=38;sun.shadow.camera.near=1;sun.shadow.camera.far=120;sun.shadow.normalBias=.018;scene.add(sun,new THREE.HemisphereLight('#d9eaff','#a9a495',2.2));
$('#sun').oninput=()=>{const a=Number($('#sun').value)*Math.PI/180;sun.position.set(40*Math.cos(a),42,40*Math.sin(a));sun.shadow.needsUpdate=true};
$('#exposure').oninput=()=>renderer.toneMappingExposure=Number($('#exposure').value)/100;
let mode='exterior',floor=1,model,manifest,enabledBubbles=true,tour=null,walkYaw=0,walkPitch=0,last=performance.now(),lastFrame=0;
const keys=new Set(),clipPlane=new THREE.Plane(new THREE.Vector3(0,-1,0),1000);
renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('#gpuFallback').hidden=false;status('การแสดงผล 3 มิติหยุดทำงานบนอุปกรณ์นี้')});
const sheetLabels=['ID-101 · เฟอร์นิเจอร์ชั้น 1','ID-102 · เฟอร์นิเจอร์ชั้น 2','ID-103 · เฟอร์นิเจอร์ชั้น 3','EL-101 · แสงสว่างชั้น 1','EL-102 · แสงสว่างชั้น 2','EL-103 · แสงสว่างชั้น 3','EP-101 · เต้ารับชั้น 1','EP-102 · เต้ารับชั้น 2','EP-103 · เต้ารับชั้น 3','AC-101 · ปรับอากาศชั้น 1','AC-102 · ปรับอากาศชั้น 2','AC-103 · ปรับอากาศชั้น 3'];
const spaces={
1:[['ห้องน้ำ',.1,.15,.26,.32],['ประชุมใหญ่',.08,.72,.28,.6],['ห้องประชุมย่อย 1',.3,.76,.38,.58],['ห้องประชุมย่อย 2',.48,.76,.47,.58],['ห้องประชุมย่อย 3',.68,.76,.57,.58],['ห้องประชุมย่อย 4',.83,.76,.66,.58],['ประชุมส่วนกลาง',.72,.4,.59,.45],['Semi-outdoor',.7,.16,.53,.32],['บันไดกลาง',.48,.19,.45,.33]],
2:[['ห้องประชุม',.18,.22,.3,.3],['พื้นที่สัมมนา',.62,.65,.55,.56],['บันได Outdoor',.48,.2,.45,.32],['พื้นที่ภายนอก',.94,.54,.71,.49],['พื้นที่พักผ่อน',.35,.25,.36,.3]],
3:[['ห้องส่วนตัว',.2,.25,.3,.31],['ห้องทำงาน',.36,.38,.39,.39],['ห้องนั่งเล่น',.25,.74,.36,.57],['ดาดฟ้า Outdoor',.66,.58,.58,.54],['บันได Outdoor',.48,.2,.45,.32]]
};

function status(s){$('#status').textContent=s}
function layerHeight(f){const b=manifest.structureBounds;return b[0][1]+(f-1)*3.15}
function cutHeight(f){return layerHeight(f)+3.15}
function worldPoint(rx,rz,f){const b=manifest.structureBounds;return new THREE.Vector3(THREE.MathUtils.lerp(b[0][0],b[1][0],rx),layerHeight(f)+1.65,THREE.MathUtils.lerp(b[0][2],b[1][2],rz))}
function frameModel(){const b=new THREE.Box3(new THREE.Vector3(...manifest.bounds[0]),new THREE.Vector3(...manifest.bounds[1]));const size=b.getSize(new THREE.Vector3()),center=b.getCenter(new THREE.Vector3());camera=mode==='iso'?ortho:perspective;controls.object=camera;controls.enabled=true;controls.target.copy(center);const aspect=innerWidth/innerHeight,d=Math.max(size.x,size.z)*1.2*(mobile?Math.max(1,.9/aspect):1);camera.position.set(center.x+d*.62,center.y+d*.55,center.z+d*.8);if(camera===ortho){const s=Math.max(size.x,size.z)*.7;ortho.left=-s*aspect;ortho.right=s*aspect;ortho.top=s;ortho.bottom=-s;ortho.updateProjectionMatrix()}camera.lookAt(center);controls.update()}
function frameFloor(){const b=manifest.structureBounds,center=new THREE.Vector3((b[0][0]+b[1][0])/2,layerHeight(floor)+1,(b[0][2]+b[1][2])/2);camera=ortho;controls.object=camera;controls.enabled=true;controls.target.copy(center);const span=Math.max(b[1][0]-b[0][0],b[1][2]-b[0][2])*1.1;camera.position.copy(center).add(new THREE.Vector3(span*.65,span*.85,span*.75));ortho.left=-span*innerWidth/innerHeight;ortho.right=span*innerWidth/innerHeight;ortho.top=span;ortho.bottom=-span;ortho.updateProjectionMatrix();camera.lookAt(center);controls.update()}
function look(){camera.rotation.order='YXZ';camera.rotation.y=walkYaw;camera.rotation.x=walkPitch;camera.rotation.z=0}
function moveToRoom(){const i=$('#roomSelect').selectedIndex,room=spaces[floor][Math.max(0,i)];const p=worldPoint(room[1],room[2],floor);camera=perspective;controls.object=camera;controls.enabled=false;camera.position.copy(p);walkYaw=Math.PI*.8;walkPitch=0;look();status(`ชั้น ${floor} · ${room[0]} · กล้องระดับสายตา`)}
function rebuildRoomSelect(){const select=$('#roomSelect');select.replaceChildren(...spaces[floor].map((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r[0];return o}));select.onchange=()=>{tour=null;moveToRoom()}}
function renderPlan(){const i=floor.toString().padStart(2,'0');$('#planImage').src=`./construction/plan-page-${i}.png`;$('#planTitle').textContent=sheetLabels[floor-1];status(`แบบก่อสร้าง · ${sheetLabels[floor-1]}`);requestAnimationFrame(updateBubbles)}
function updateBubbles(){bubbleLayer.replaceChildren();if(!enabledBubbles||!['plan','iso'].includes(mode))return;const rect=$('#planImage').getBoundingClientRect();for(const [name,x,z,px,py] of spaces[floor]){const el=document.createElement('div');el.className='bubble';el.textContent=name;let sx,sy;if(mode==='plan'){sx=rect.left+rect.width*px;sy=rect.top+rect.height*py}else{const p=worldPoint(x,z,floor);p.y=layerHeight(floor)+.8;p.project(camera);if(p.z< -1||p.z>1)continue;sx=(p.x*.5+.5)*innerWidth;sy=(-p.y*.5+.5)*innerHeight}if(sx<5||sx>innerWidth-5||sy<5||sy>innerHeight-5)continue;el.style.left=sx+'px';el.style.top=sy+'px';bubbleLayer.append(el)}}
function setMode(next){tour=null;mode=next;if(document.pointerLockElement)document.exitPointerLock();document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));const plan=mode==='plan';$('#stage').style.visibility=plan?'hidden':'visible';$('#plans').style.display=plan?'flex':'none';$('#planInfo').style.display=plan?'block':'none';$('#settings').style.display=plan?'none':'block';$('#tourbar').style.display=['walk','tour'].includes(mode)?'flex':'none';$('#floor').disabled=mode==='exterior';clipPlane.constant=['exterior','plan'].includes(mode)?1000:cutHeight(floor);model?.traverse(m=>{if(m.isMesh){m.material.clippingPlanes=mode==='exterior'?[]:[clipPlane];m.material.needsUpdate=true}});if(mode==='exterior'){frameModel();status('โมเดล SketchUp ล่าสุด · มุมภายนอก')}else if(mode==='iso'){frameFloor();status(`โมเดล SketchUp ล่าสุด · ชั้น ${floor}`)}else if(plan)renderPlan();else{rebuildRoomSelect();moveToRoom()}updateBubbles()}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
$('#floor').onchange=()=>{floor=Number($('#floor').value);setMode(mode)};
$('#reset').onclick=()=>setMode(mode);
$('#bubbleToggle').onclick=()=>{enabledBubbles=!enabledBubbles;$('#bubbleToggle').textContent='ป้ายพื้นที่: '+(enabledBubbles?'เปิด':'ปิด');$('#bubbleToggle').setAttribute('aria-pressed',String(enabledBubbles));updateBubbles()};
$('#playTour').onclick=()=>{if(mode!=='tour')setMode('tour');const i=$('#roomSelect').selectedIndex,room=spaces[floor][Math.max(i,0)],p=worldPoint(room[1],room[2],floor);tour={start:performance.now(),center:p.clone(),base:p.clone().add(new THREE.Vector3(-.9,0,-.6))};camera.position.copy(tour.base);status(`กำลังพาชม ${room[0]} · กล้องระดับสายตา`)};
$('#prevRoom').onclick=()=>{const s=$('#roomSelect');s.selectedIndex=(s.selectedIndex-1+s.options.length)%s.options.length;moveToRoom()};
$('#nextRoom').onclick=()=>{const s=$('#roomSelect');s.selectedIndex=(s.selectedIndex+1)%s.options.length;moveToRoom()};
$('#walkStart').onclick=async()=>{try{await renderer.domElement.requestPointerLock()}catch{status('ลากบนภาพเพื่อมองรอบตัว')}};
document.addEventListener('pointerlockchange',()=>{$('#reticle').style.display=document.pointerLockElement?'block':'none';$('#walkStart').textContent=document.pointerLockElement?'Esc คืนเมาส์':'คลิกเพื่อเดิน'});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement!==renderer.domElement||!['walk','tour'].includes(mode))return;tour=null;walkYaw-=e.movementX*.0025;walkPitch=THREE.MathUtils.clamp(walkPitch-e.movementY*.0025,-1.25,1.25);look()});
document.addEventListener('keydown',e=>{keys.add(e.key.toLowerCase());if(e.key==='Escape')tour=null});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
renderer.domElement.addEventListener('pointermove',e=>{if(document.pointerLockElement||!['walk','tour'].includes(mode)||e.buttons!==1)return;tour=null;walkYaw-=e.movementX*.004;walkPitch=THREE.MathUtils.clamp(walkPitch-e.movementY*.004,-1.25,1.25);look()});
$('#sheetsButton').onclick=()=>$('#sheets').showModal();$('#aboutButton').onclick=()=>$('#about').showModal();$('#planSheet').onclick=()=>showSheet(floor-1);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
function showSheet(i){$('#sheetTitle').textContent=sheetLabels[i];$('#sheetImage').src=`./construction/plan-page-${String(i+1).padStart(2,'0')}.png`;$('#sheetLarge').showModal()}
$('#sheetGrid').replaceChildren(...sheetLabels.map((label,i)=>{const b=document.createElement('button'),img=document.createElement('img'),span=document.createElement('span');img.loading='lazy';img.src=`./construction/plan-page-${String(i+1).padStart(2,'0')}.png`;img.alt=label;span.textContent=label;b.append(img,span);b.onclick=()=>showSheet(i);return b}));
onresize=()=>{renderer.setSize(innerWidth,innerHeight);perspective.aspect=innerWidth/innerHeight;perspective.updateProjectionMatrix();if(!manifest)return;if(mode==='iso')frameFloor();else if(mode==='exterior')frameModel();updateBubbles()};

function addFloorOneToilets(){
 const porcelain=new THREE.MeshPhysicalMaterial({name:'สุขภัณฑ์เซรามิก',color:'#f3f1ea',roughness:.2,metalness:0,clearcoat:.28,clearcoatRoughness:.18});
 const water=new THREE.MeshStandardMaterial({name:'น้ำในโถ',color:'#617b80',roughness:.16,metalness:.05});
 const chrome=new THREE.MeshStandardMaterial({name:'ปุ่มกดโครเมียม',color:'#bac4c6',roughness:.25,metalness:.62});
 const make=(geometry,material,x,y,z,parent)=>{const mesh=new THREE.Mesh(geometry,material);mesh.position.set(x,y,z);mesh.castShadow=false;mesh.receiveShadow=true;parent.add(mesh);return mesh};
 for(const z of [-44.6,-43.25,-41.9]){
  const unit=new THREE.Group();unit.position.set(-53.9,.02,z);
  const pedestal=make(new THREE.CylinderGeometry(.22,.19,.34,18),porcelain,0,.22,0,unit);pedestal.scale.z=1.25;
  const bowl=make(new THREE.SphereGeometry(.29,20,12),porcelain,0,.42,-.12,unit);bowl.scale.set(1,.35,1.3);
  const opening=make(new THREE.CircleGeometry(.19,20),water,0,.518,-.12,unit);opening.rotation.x=-Math.PI/2;opening.scale.y=1.3;
  const seat=make(new THREE.TorusGeometry(.225,.035,8,24),porcelain,0,.525,-.12,unit);seat.rotation.x=-Math.PI/2;seat.scale.y=1.28;
  make(new THREE.BoxGeometry(.48,.48,.17),porcelain,0,.67,.37,unit);
  make(new THREE.BoxGeometry(.16,.025,.08),chrome,0,.92,.36,unit);
  model.add(unit);
 }
}

async function loadModel(){const manifestFile='./optimized-model-v5-manifest.json';const manifestResponse=await fetch(manifestFile);if(!manifestResponse.ok)throw Error('ไม่พบข้อมูลโมเดล');manifest=await manifestResponse.json();let loaded=0;const parts=await Promise.all(manifest.parts.map(async(n,i)=>{const response=await fetch('./'+n);if(!response.ok)throw Error(`ข้อมูลโมเดลส่วน ${i+1} โหลดไม่ได้`);const bytes=new Uint8Array(await response.arrayBuffer());loaded++;$('#loadingText').textContent=`กำลังโหลดโมเดล ${Math.round(loaded/manifest.parts.length*100)}%`;return bytes}));const zipped=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let off=0;for(const part of parts){zipped.set(part,off);off+=part.length}$('#loadingText').textContent='กำลังจัดรูปทรงและวัสดุ';const raw=await new Response(new Blob([zipped]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();const gltf=await new GLTFLoader().parseAsync(raw,'');const source=gltf.scene;source.updateMatrixWorld(true);const groups=new Map(),instanced=[];source.traverse(m=>{if(!m.isMesh)return;if(m.isInstancedMesh){instanced.push(m);return}const key=m.geometry.uuid+':'+m.material.uuid;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m)});model=new THREE.Group();for(const m of instanced){const material=m.material;if(/glass|translucent|กระจก/i.test(material.name)){material.transparent=true;material.opacity=.23;material.depthWrite=false;material.roughness=.16}else material.roughness=Math.max(.48,material.roughness||.7);material.side=THREE.DoubleSide;const world=m.matrixWorld.clone();model.add(m);m.matrixAutoUpdate=false;m.matrix.copy(world);m.castShadow=false;m.receiveShadow=true}for(const list of groups.values()){const first=list[0],material=first.material;if(/glass|translucent|กระจก/i.test(material.name)){material.transparent=true;material.opacity=.23;material.depthWrite=false;material.roughness=.16;material.side=THREE.DoubleSide}else{material.roughness=Math.max(.48,material.roughness||.7);material.side=THREE.DoubleSide}if(list.length>1&&!material.transparent){const mesh=new THREE.InstancedMesh(first.geometry,material,list.length);list.forEach((m,i)=>mesh.setMatrixAt(i,m.matrixWorld));mesh.instanceMatrix.needsUpdate=true;mesh.castShadow=false;mesh.receiveShadow=true;model.add(mesh)}else for(const m of list){const mesh=new THREE.Mesh(m.geometry,material);mesh.applyMatrix4(m.matrixWorld);mesh.castShadow=!material.transparent;mesh.receiveShadow=true;model.add(mesh)}}addFloorOneToilets();scene.add(model);$('#loading').style.display='none';setMode('exterior')}
function finishMaterials(){const seen=new Set();model.traverse(mesh=>{if(!mesh.isMesh)return;const material=mesh.material;if(!material||seen.has(material))return;seen.add(material);const name=material.name.toLowerCase();if(/glass|translucent|กระจก/.test(name)){material.color.set('#eaf7fa');material.transparent=true;material.opacity=.18;material.roughness=.08;material.metalness=0;material.depthWrite=false}else if(/steel|aluminum|metal|chrome/.test(name)){material.metalness=.38;material.roughness=.36}else if(/wood|veneer|madeira|formica/.test(name)){material.metalness=0;material.roughness=.57}else if(/concrete|cement|plaster|ivory/.test(name)){material.metalness=0;material.roughness=.86}else if(/tile|ceramic|porcelain|กระเบื้อง|สุขภัณฑ์/.test(name)){material.metalness=0;material.roughness=.32}else{material.metalness=0;material.roughness=material.map ? .68 : .73}if(material.map)material.map.anisotropy=mobile?2:4;material.needsUpdate=true})}
loadModel().then(finishMaterials).catch(err=>{$('#loading').style.display='none';$('#gpuFallback').hidden=false;status('เปิดโมเดลไม่สำเร็จ: '+err.message);console.error(err)});
function animate(now){requestAnimationFrame(animate);if(now-lastFrame<(mobile?1000/30:1000/45))return;lastFrame=now;const dt=Math.min((now-last)/1000,.05);last=now;if(tour){const t=Math.min((now-tour.start)/7500,1),e=t*t*(3-2*t),a=e*Math.PI*.7;camera.position.set(tour.center.x+Math.cos(a)*1.25, tour.center.y,tour.center.z+Math.sin(a)*1.25);camera.lookAt(tour.center.x+Math.cos(a+.75)*2,tour.center.y,tour.center.z+Math.sin(a+.75)*2);if(t===1){tour=null;status('ทัวร์เร็วเสร็จแล้ว · เลือกห้องอื่นได้')}}if(['walk','tour'].includes(mode)&&!tour){const speed=2.1*dt,forward=new THREE.Vector3(-Math.sin(walkYaw),0,-Math.cos(walkYaw)),side=new THREE.Vector3(forward.z,0,-forward.x);if(keys.has('w')||keys.has('arrowup'))camera.position.addScaledVector(forward,speed);if(keys.has('s')||keys.has('arrowdown'))camera.position.addScaledVector(forward,-speed);if(keys.has('a')||keys.has('arrowleft'))camera.position.addScaledVector(side,-speed);if(keys.has('d')||keys.has('arrowright'))camera.position.addScaledVector(side,speed);const b=manifest?.structureBounds;if(b){camera.position.x=THREE.MathUtils.clamp(camera.position.x,b[0][0]-.5,b[1][0]+.5);camera.position.z=THREE.MathUtils.clamp(camera.position.z,b[0][2]-.5,b[1][2]+.5);camera.position.y=layerHeight(floor)+1.65}}if(mode==='iso'){controls.update();updateBubbles()}else if(mode==='exterior')controls.update();renderer.render(scene,camera)}requestAnimationFrame(animate);
